from __future__ import annotations
import re


def parse_metric_value(value_str) -> float:  # string value with optional unit suffix (K, M, G)
    """Convert string values with units (K, M, G) to float in millions.
    
    Uses regex for precise suffix matching to avoid false positives
    (e.g., 'GPU' would incorrectly match 'G' with simple `in` check).
    """
    if isinstance(value_str, (int, float)):
        return float(value_str)

    value_str = str(value_str).strip().upper()
    match = re.match(r'^([\d.]+)\s*([KMG])?$', value_str)
    if not match:
        raise ValueError(f"Cannot parse metric value: {value_str!r}")

    num = float(match.group(1))
    suffix = match.group(2)
    multipliers = {'K': 0.001, 'M': 1.0, 'G': 1000.0}
    return num * multipliers.get(suffix, 1.0)

